Lemma geo_1RB0LC_0LC1RA_0RA1LD_0RB1LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_0LC1RA_0RA1LD_0RB1LC) = lift (Cc (Pos.succ p)).
