(** ** The lap *)

Lemma lap_1RB0LC_0LC1RA_0RA1LD_1LA1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
