  - destruct (lapi_1RB0LC_0LC1RA_0RA1LD_1LA1LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LC_0LC1RA_0RA1LD_1LA1LC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LC_0LC1RA_0RA1LD_1LA1LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 4.
  assert (H : match csteps tm 4 c0 with
