(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LC_0LC1RA_0RA1LD_1LA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_0LC1RA_0RA1LD_1LA1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LC_0LC1RA_0RA1LD_1LA1LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_0LC1RA_0RA1LD_1LA1LC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB0LC_0LC1RA_0RA1LD_1LA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0LC_0LC1RA_0RA1LD_1LA1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0LC_0LC1RA_0RA1LD_1LA1LC t p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB0LC_0LC1RA_0RA1LD_1LA1LC). split;
      [| exact (gbo_1RB0LC_0LC1RA_0RA1LD_1LA1LC j)].
    rewrite (gso_1RB0LC_0LC1RA_0RA1LD_1LA1LC p j E).
    exact (srun_sound tm true true chb_1RB0LC_0LC1RA_0RA1LD_1LA1LC B0_1RB0LC_0LC1RA_0RA1LD_1LA1LC BB1_1RB0LC_0LC1RA_0RA1LD_1LA1LC 4 8
             run_boot_1RB0LC_0LC1RA_0RA1LD_1LA1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0LC_0LC1RA_0RA1LD_1LA1LC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0LC_0LC1RA_0RA1LD_1LA1LC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LC_0LC1RA_0RA1LD_1LA1LC : forall t, ~ In t pins_1RB0LC_0LC1RA_0RA1LD_1LA1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0LC_0LC1RA_0RA1LD_1LA1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0LC1RA_0RA1LD_1LA1LC [] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0LC1RA_0RA1LD_1LA1LC [SCycL 2 0; SWin 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LC_0LC1RA_0RA1LD_1LA1LC (StB, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LC_0LC1RA_0RA1LD_1LA1LC [SCycL 2 0; SWin 1; SWinL 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0LC1RA_0RA1LD_1LA1LC [SCycL 2 0; SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0LC1RA_0RA1LD_1LA1LC [SCycL 2 0; SWin 4; SCycR 2; SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0LC1RA_0RA1LD_1LA1LC [SCycL 2 0; SWin 3] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LC_0LC1RA_0RA1LD_1LA1LC (StD, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LC_0LC1RA_0RA1LD_1LA1LC [SCycL 2 0; SWin 1; SWinL 5; SCycR 2; SWinR 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0LC1RA_0RA1LD_1LA1LC [SCycL 2 0; SWin 4] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_1RB0LC_0LC1RA_0RA1LD_1LA1LC : NeverQuasiHaltsTr tmm_1RB0LC_0LC1RA_0RA1LD_1LA1LC.
Proof.
  apply (glue_neverqhtr tmm_1RB0LC_0LC1RA_0RA1LD_1LA1LC pins_1RB0LC_0LC1RA_0RA1LD_1LA1LC Cc 1).
