  exists (6 * j + 10), (cden (Jp q0 ++ [S0]) [] j A1_1RB0LC_0LC1RA_0RA1LD_1LC0RC).
  split; [lia|]. split; [| exact (gei_1RB0LC_0LC1RA_0RA1LD_1LC0RC p j q0 E)].
  rewrite (gsi_1RB0LC_0LC1RA_0RA1LD_1LC0RC p j q0 E).
