    apply (lap_of_run tm Cc true true cho_1RB0LC_0LC1RA_0RA1LD_1RC1LC B0_1RB0LC_0LC1RA_0RA1LD_1RC1LC B1_1RB0LC_0LC1RA_0RA1LD_1RC1LC 4 13 p j' [] []).
    + exact run_ovf_1RB0LC_0LC1RA_0RA1LD_1RC1LC.
