(** 1RB0LC_0LC1RD_0RA1LA_1LC1RB *)
(** 1RB0LC_0LC1RD_0RA1LA_1LC1RB -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0LC_0LC1RD_0RA1LA_1LC1RB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S0 DR StA | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S1 DL StC | StD, S1 => mk S1 DR StB end.

(** Its mirror 1LB0RC_0RC1LD_0LA1RA_1RC1LB: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LC_0LC1RD_0RA1LA_1LC1RB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S1 DL StD
  | StC, S0 => mk S0 DL StA | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S1 DL StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LC_0LC1RD_0RA1LA_1LC1RB : list Instr := [].
Definition tmw_1RB0LC_0LC1RD_0RA1LA_1LC1RB : TM := tm_wrap_trs tmm_1RB0LC_0LC1RD_0RA1LA_1LC1RB pins_1RB0LC_0LC1RD_0RA1LA_1LC1RB.
Local Notation tm := tmw_1RB0LC_0LC1RD_0RA1LA_1LC1RB.

Lemma mirror_ok_1RB0LC_0LC1RD_0RA1LA_1LC1RB : mirror_tm tm_1RB0LC_0LC1RD_0RA1LA_1LC1RB = tmm_1RB0LC_0LC1RD_0RA1LA_1LC1RB.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

