(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_1RB0LC_0LC1RD_0RA1LA_1LC1RB : forall j, lift (cden [] [] j BB1_1RB0LC_0LC1RD_0RA1LA_1LC1RB) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LC_0LC1RD_0RA1LA_1LC1RB = (StA, (rep [S1;S0] j ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB0LC_0LC1RD_0RA1LA_1LC1RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB0LC_0LC1RD_0RA1LA_1LC1RB. rewrite epow2_1RB0LC_0LC1RD_0RA1LA_1LC1RB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LC_0LC1RD_0RA1LA_1LC1RB. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LC_0LC1RD_0RA1LA_1LC1RB : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB0LC_0LC1RD_0RA1LA_1LC1RB.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0LC_0LC1RD_0RA1LA_1LC1RB, cden, BE0_1RB0LC_0LC1RD_0RA1LA_1LC1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0LC_0LC1RD_0RA1LA_1LC1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB0LC_0LC1RD_0RA1LA_1LC1RB. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LC_0LC1RD_0RA1LA_1LC1RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LC_0LC1RD_0RA1LA_1LC1RB p (pow2 j)).
  - exists (4 * j + 6), (cden [] [] j BB1_1RB0LC_0LC1RD_0RA1LA_1LC1RB).
    split; [lia|]. split; [| exact (gbo_1RB0LC_0LC1RD_0RA1LA_1LC1RB j)].
    rewrite (gso_1RB0LC_0LC1RD_0RA1LA_1LC1RB p j E).
    exact (srun_sound tm true true chb_1RB0LC_0LC1RD_0RA1LA_1LC1RB B0_1RB0LC_0LC1RD_0RA1LA_1LC1RB BB1_1RB0LC_0LC1RD_0RA1LA_1LC1RB 4 6
             run_boot_1RB0LC_0LC1RD_0RA1LA_1LC1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 7), (cden [] [] j B1_1RB0LC_0LC1RD_0RA1LA_1LC1RB).
    split; [| exact (geo_1RB0LC_0LC1RD_0RA1LA_1LC1RB p j E)].
    rewrite (gxi_1RB0LC_0LC1RD_0RA1LA_1LC1RB j).
    exact (srun_sound tm true true che_1RB0LC_0LC1RD_0RA1LA_1LC1RB BE0_1RB0LC_0LC1RD_0RA1LA_1LC1RB B1_1RB0LC_0LC1RD_0RA1LA_1LC1RB 4 7
             run_exit_1RB0LC_0LC1RD_0RA1LA_1LC1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LC_0LC1RD_0RA1LA_1LC1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LC_0LC1RD_0RA1LA_1LC1RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LC_0LC1RD_0RA1LA_1LC1RB p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LC_0LC1RD_0RA1LA_1LC1RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 3.
  assert (H : match csteps tm 3 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 3 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LC_0LC1RD_0RA1LA_1LC1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_0LC1RD_0RA1LA_1LC1RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LC_0LC1RD_0RA1LA_1LC1RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_0LC1RD_0RA1LA_1LC1RB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB0LC_0LC1RD_0RA1LA_1LC1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0LC_0LC1RD_0RA1LA_1LC1RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0LC_0LC1RD_0RA1LA_1LC1RB t p (pow2 j)).
  - exists (4 * j + 6), (cden [] [] j BB1_1RB0LC_0LC1RD_0RA1LA_1LC1RB). split;
      [| exact (gbo_1RB0LC_0LC1RD_0RA1LA_1LC1RB j)].
    rewrite (gso_1RB0LC_0LC1RD_0RA1LA_1LC1RB p j E).
    exact (srun_sound tm true true chb_1RB0LC_0LC1RD_0RA1LA_1LC1RB B0_1RB0LC_0LC1RD_0RA1LA_1LC1RB BB1_1RB0LC_0LC1RD_0RA1LA_1LC1RB 4 6
             run_boot_1RB0LC_0LC1RD_0RA1LA_1LC1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0LC_0LC1RD_0RA1LA_1LC1RB xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0LC_0LC1RD_0RA1LA_1LC1RB j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LC_0LC1RD_0RA1LA_1LC1RB : forall t, ~ In t pins_1RB0LC_0LC1RD_0RA1LA_1LC1RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0LC_0LC1RD_0RA1LA_1LC1RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0LC1RD_0RA1LA_1LC1RB [] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0LC1RD_0RA1LA_1LC1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LC_0LC1RD_0RA1LA_1LC1RB (StB, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LC_0LC1RD_0RA1LA_1LC1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0LC1RD_0RA1LA_1LC1RB [SRotL 1; SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0LC1RD_0RA1LA_1LC1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0LC1RD_0RA1LA_1LC1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0LC1RD_0RA1LA_1LC1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LC_0LC1RD_0RA1LA_1LC1RB (StD, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0LC_0LC1RD_0RA1LA_1LC1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_1RB0LC_0LC1RD_0RA1LA_1LC1RB : NeverQuasiHaltsTr tmm_1RB0LC_0LC1RD_0RA1LA_1LC1RB.
Proof.
  apply (glue_neverqhtr tmm_1RB0LC_0LC1RD_0RA1LA_1LC1RB pins_1RB0LC_0LC1RD_0RA1LA_1LC1RB Cc 1).
  - exact boot_1RB0LC_0LC1RD_0RA1LA_1LC1RB.
  - intros p _. apply lap_1RB0LC_0LC1RD_0RA1LA_1LC1RB.
  - intros t Ht p _. apply fire_1RB0LC_0LC1RD_0RA1LA_1LC1RB. exact Ht.
Qed.

Theorem nqhtr_1RB0LC_0LC1RD_0RA1LA_1LC1RB : NeverQuasiHaltsTr tm_1RB0LC_0LC1RD_0RA1LA_1LC1RB.
Proof. apply (neverqhtr_mirror tm_1RB0LC_0LC1RD_0RA1LA_1LC1RB). rewrite mirror_ok_1RB0LC_0LC1RD_0RA1LA_1LC1RB. exact nqhtrm_1RB0LC_0LC1RD_0RA1LA_1LC1RB. Qed.

Theorem nonhalt_1RB0LC_0LC1RD_0RA1LA_1LC1RB : NonHalt tm_1RB0LC_0LC1RD_0RA1LA_1LC1RB.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB0LC_0LC1RD_0RA1LA_1LC1RB. Qed.

