Lemma gsn_1RB0LC_0LC1RD_0RC1LA_1LC1RB : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_1RB0LC_0LC1RD_0RC1LA_1LC1RB.
