  unfold Cin_1RB0LC_0LC1RD_0RC1LA_1LC1RB, cden, AI0_1RB0LC_0LC1RD_0RC1LA_1LC1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB0LC_0LC1RD_0RC1LA_1LC1RB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB0LC_0LC1RD_0RC1LA_1LC1RB) = lift (Cin (Pos.succ v)).
Proof.
