  unfold Cin_1RB0LC_0LC1RD_0RC1LA_1LC1RB, cden, BE0_1RB0LC_0LC1RD_0RC1LA_1LC1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
