(** ** The lap *)

Lemma lap_1RB0LC_0LC1RD_0RC1LA_1LC1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
