(** ** Bootstrap *)

Lemma boot_1RB0LC_0LC1RD_0RC1LA_1LC1RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 3.
  assert (H : match csteps tm 3 c0 with
