(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LC_0LC1RD_0RC1LA_1LC1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_0LC1RD_0RC1LA_1LC1RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LC_0LC1RD_0RC1LA_1LC1RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_0LC1RD_0RC1LA_1LC1RB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB0LC_0LC1RD_0RC1LA_1LC1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0LC_0LC1RD_0RC1LA_1LC1RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0LC_0LC1RD_0RC1LA_1LC1RB t p (pow2 j)).
  - exists (4 * j + 6), (cden [] [] j BB1_1RB0LC_0LC1RD_0RC1LA_1LC1RB). split;
      [| exact (gbo_1RB0LC_0LC1RD_0RC1LA_1LC1RB j)].
