    exact (srun_sound tm true true chb_1RB0LC_0LC1RD_0RC1LA_1LC1RB B0_1RB0LC_0LC1RD_0RC1LA_1LC1RB BB1_1RB0LC_0LC1RD_0RC1LA_1LC1RB 4 6
             run_boot_1RB0LC_0LC1RD_0RC1LA_1LC1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
