  exact (srun_sound tm false true chi_1RB0LC_0LC1RD_0RD1LA_1LC1RB A0_1RB0LC_0LC1RD_0RD1LA_1LC1RB A1_1RB0LC_0LC1RD_0RD1LA_1LC1RB 4 8
