Lemma geo_1RB0LC_0LC1RD_0RD1LA_1LC1RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_0LC1RD_0RD1LA_1LC1RB) = lift (Cc (Pos.succ p)).
