(** The chain into this family lands on its anchor up to 1/0
    trailing blanks. *)
Lemma gbo_1RB0LC_0LC1RD_0RD1LA_1LC1RB : forall j, lift (cden [] [] j BB1_1RB0LC_0LC1RD_0RD1LA_1LC1RB) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LC_0LC1RD_0RD1LA_1LC1RB = (StD, ((rep [S1;S0] j ++ [S1]) ++ [S0], S0, [S1;S1]))).
  { unfold cden, BB1_1RB0LC_0LC1RD_0RD1LA_1LC1RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
