  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LC_0LC1RD_0RD1LA_1LC1RB p (pow2 j)).
  - exists (4 * j + 11), (cden [] [] j BB1_1RB0LC_0LC1RD_0RD1LA_1LC1RB).
    split; [lia|]. split; [| exact (gbo_1RB0LC_0LC1RD_0RD1LA_1LC1RB j)].
    rewrite (gso_1RB0LC_0LC1RD_0RD1LA_1LC1RB p j E).
    exact (srun_sound tm true true chb_1RB0LC_0LC1RD_0RD1LA_1LC1RB B0_1RB0LC_0LC1RD_0RD1LA_1LC1RB BB1_1RB0LC_0LC1RD_0RD1LA_1LC1RB 4 11
             run_boot_1RB0LC_0LC1RD_0RD1LA_1LC1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 16), (cden [] [] j B1_1RB0LC_0LC1RD_0RD1LA_1LC1RB).
    split; [| exact (geo_1RB0LC_0LC1RD_0RD1LA_1LC1RB p j E)].
    rewrite (gxi_1RB0LC_0LC1RD_0RD1LA_1LC1RB j).
    exact (srun_sound tm true true che_1RB0LC_0LC1RD_0RD1LA_1LC1RB BE0_1RB0LC_0LC1RD_0RD1LA_1LC1RB B1_1RB0LC_0LC1RD_0RD1LA_1LC1RB 4 16
             run_exit_1RB0LC_0LC1RD_0RD1LA_1LC1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LC_0LC1RD_0RD1LA_1LC1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LC_0LC1RD_0RD1LA_1LC1RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LC_0LC1RD_0RD1LA_1LC1RB p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LC_0LC1RD_0RD1LA_1LC1RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 9.
  assert (H : match csteps tm 9 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 9 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LC_0LC1RD_0RD1LA_1LC1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_0LC1RD_0RD1LA_1LC1RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LC_0LC1RD_0RD1LA_1LC1RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_0LC1RD_0RD1LA_1LC1RB p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LC_0LC1RD_0RD1LA_1LC1RB : forall t, ~ In t pins_1RB0LC_0LC1RD_0RD1LA_1LC1RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
