(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LC_0RC0LB_0RD1LA_1LC1RD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LC_0RC0LB_0RD1LA_1LC1RD p (pow2 j)).
  - exists (4 * j + 13), (cden [] [] j BB1_1RB0LC_0RC0LB_0RD1LA_1LC1RD).
    split; [lia|]. split; [| exact (gbo_1RB0LC_0RC0LB_0RD1LA_1LC1RD j)].
    rewrite (gso_1RB0LC_0RC0LB_0RD1LA_1LC1RD p j E).
    exact (srun_sound tm true true chb_1RB0LC_0RC0LB_0RD1LA_1LC1RD B0_1RB0LC_0RC0LB_0RD1LA_1LC1RD BB1_1RB0LC_0RC0LB_0RD1LA_1LC1RD 4 13
