Lemma mirror_ok_1RB0LC_0RC1RA_1LC1LD_0RB1LD : mirror_tm tm_1RB0LC_0RC1RA_1LC1LD_0RB1LD = tmm_1RB0LC_0RC1RA_1LC1LD_0RB1LD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0LC_0RC1RA_1LC1LD_0RB1LD (p : positive) : cconf := (StD, (Jp p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB0LC_0RC1RA_1LC1LD_0RB1LD.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_1RB0LC_0RC1RA_1LC1LD_0RB1LD : sconf := mkC StD (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_1RB0LC_0RC1RA_1LC1LD_0RB1LD : sconf := mkC StD (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
