(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
    a concrete cell to step onto. *)
Definition P0_1RB0LC_0RC1RA_1LC1LD_0RB1LD : sconf := mkC StD (mkS [S1;S0] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition P1_1RB0LC_0RC1RA_1LC1LD_0RB1LD : sconf := mkC StD (mkS [S1;S1] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition chp_1RB0LC_0RC1RA_1LC1LD_0RB1LD : list lstep := [SWin 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_p_1RB0LC_0RC1RA_1LC1LD_0RB1LD : srun tm false true chp_1RB0LC_0RC1RA_1LC1LD_0RB1LD P0_1RB0LC_0RC1RA_1LC1LD_0RB1LD = Some (P1_1RB0LC_0RC1RA_1LC1LD_0RB1LD, 4, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB0LC_0RC1RA_1LC1LD_0RB1LD : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB0LC_0RC1RA_1LC1LD_0RB1LD : sconf := mkC StD (mkS [] [S1;S1] 1 1 [S1;S0]) S0 (mkS [] [] 0 0 []).
