Definition chn_1RB0LC_0RC1RA_1LC1LD_0RB1LD : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWin 1; SWinR 7].

Lemma run_inner_1RB0LC_0RC1RA_1LC1LD_0RB1LD : srun tm false true chn_1RB0LC_0RC1RA_1LC1LD_0RB1LD AI0_1RB0LC_0RC1RA_1LC1LD_0RB1LD = Some (AI1_1RB0LC_0RC1RA_1LC1LD_0RB1LD, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB0LC_0RC1RA_1LC1LD_0RB1LD : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [S1;S0] [] 0 0 []).
Definition chb_1RB0LC_0RC1RA_1LC1LD_0RB1LD : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 5; SCycR 2; SWin 2; SRotL 1; SWin 5].

Lemma run_boot_1RB0LC_0RC1RA_1LC1LD_0RB1LD : srun tm true true chb_1RB0LC_0RC1RA_1LC1LD_0RB1LD B0_1RB0LC_0RC1RA_1LC1LD_0RB1LD = Some (BB1_1RB0LC_0RC1RA_1LC1LD_0RB1LD, 4, 14).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
