Definition che_1RB0LC_0RC1RA_1LC1LD_0RB1LD : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWin 1; SWinR 1; SFoldL 1].

Lemma run_exit_1RB0LC_0RC1RA_1LC1LD_0RB1LD : srun tm true true che_1RB0LC_0RC1RA_1LC1LD_0RB1LD BE0_1RB0LC_0RC1RA_1LC1LD_0RB1LD = Some (B1_1RB0LC_0RC1RA_1LC1LD_0RB1LD, 4, 6).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0LC_0RC1RA_1LC1LD_0RB1LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] 0 Z0_1RB0LC_0RC1RA_1LC1LD_0RB1LD /\
  cden (Jp q0 ++ [S0]) [] 0 Z1_1RB0LC_0RC1RA_1LC1LD_0RB1LD = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (JpCounter.cview_some_J p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB0LC_0RC1RA_1LC1LD_0RB1LD, cden, Z0_1RB0LC_0RC1RA_1LC1LD_0RB1LD, Z1_1RB0LC_0RC1RA_1LC1LD_0RB1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB0LC_0RC1RA_1LC1LD_0RB1LD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j P0_1RB0LC_0RC1RA_1LC1LD_0RB1LD /\
  cden (Jp q0 ++ [S0]) [] j P1_1RB0LC_0RC1RA_1LC1LD_0RB1LD = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB0LC_0RC1RA_1LC1LD_0RB1LD, cden, P0_1RB0LC_0RC1RA_1LC1LD_0RB1LD, P1_1RB0LC_0RC1RA_1LC1LD_0RB1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
