    apply (lap_of_run tm Cc true true cho_1RB0LC_0RC1RA_1LD____0RA0LD B0_1RB0LC_0RC1RA_1LD____0RA0LD B1_1RB0LC_0RC1RA_1LD____0RA0LD 4 12 p j' [] []).
    + exact run_ovf_1RB0LC_0RC1RA_1LD____0RA0LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LC_0RC1RA_1LD____0RA0LD p j' E).
    + exact (geo_1RB0LC_0RC1RA_1LD____0RA0LD p j' E).
    + lia.
