Lemma fireo_1RB0LC_0RC1RA_1LD____0RA0LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_0RC1RA_1LD____0RA0LD = Some t ->
  forall p j, cview p = (S j, None) ->
