    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0RC1RA_1LD____0RA0LD [] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0RC1RA_1LD____0RA0LD [SCycL 2 0; SWin 2; SWinL 4] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
