(** ** The lap *)

Lemma lap_1RB0LC_1LA0RA_1LD0RA_0RC1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LC_1LA0RA_1LD0RA_0RC1LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LC_1LA0RA_1LD0RA_0RC1LC B0_1RB0LC_1LA0RA_1LD0RA_0RC1LC B1_1RB0LC_1LA0RA_1LD0RA_0RC1LC 4 10 p j' [] []).
    + exact run_ovf_1RB0LC_1LA0RA_1LD0RA_0RC1LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LC_1LA0RA_1LD0RA_0RC1LC p j' E).
    + exact (geo_1RB0LC_1LA0RA_1LD0RA_0RC1LC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LC_1LA0RA_1LD0RA_0RC1LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 4.
  assert (H : match csteps tm 4 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 4 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LC_1LA0RA_1LD0RA_0RC1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_1LA0RA_1LD0RA_0RC1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LC_1LA0RA_1LD0RA_0RC1LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_1LA0RA_1LD0RA_0RC1LC p j E)].
