  unfold Cc_1RB0LC_1LA1RA_0LD1LC_0RD1RA, cden, Z0_1RB0LC_1LA1RA_0LD1LC_0RD1RA, Z1_1RB0LC_1LA1RA_0LD1LC_0RD1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
