Definition mk_1RB0LC_1LA1RA_0RA0LD____0LC (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB0LC_1LA1RA_0RA0LD____0LC.

(** 1RB0LC_1LA1RA_0RA0LD_---0LC *)
(** 1RB0LC_1LA1RA_0RA0LD_---0LC -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0LC_1LA1RA_0RA0LD____0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S0 DR StA | StC, S1 => mk S0 DL StD
  | StD, S0 => None | StD, S1 => mk S0 DL StC end.

(** Its mirror 1LB0RC_1RA1LA_0LA0RD_---0RC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LC_1LA1RA_0RA0LD____0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StA | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S0 DL StA | StC, S1 => mk S0 DR StD
  | StD, S0 => None | StD, S1 => mk S0 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LC_1LA1RA_0RA0LD____0LC : list Instr := [(StD, S0)].
Definition tmw_1RB0LC_1LA1RA_0RA0LD____0LC : TM := tm_wrap_trs tmm_1RB0LC_1LA1RA_0RA0LD____0LC pins_1RB0LC_1LA1RA_0RA0LD____0LC.
Local Notation tm := tmw_1RB0LC_1LA1RA_0RA0LD____0LC.

Lemma mirror_ok_1RB0LC_1LA1RA_0RA0LD____0LC : mirror_tm tm_1RB0LC_1LA1RA_0RA0LD____0LC = tmm_1RB0LC_1LA1RA_0RA0LD____0LC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0LC_1LA1RA_0RA0LD____0LC (p : positive) : cconf := (StA, (Ap_Alph_00_10_1 p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB0LC_1LA1RA_0RA0LD____0LC.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_1RB0LC_1LA1RA_0RA0LD____0LC : sconf := mkC StA (mkS [S0;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_1RB0LC_1LA1RA_0RA0LD____0LC : sconf := mkC StA (mkS [S1;S0] [] 0 0 []) S0 (mkS [S0] [] 0 0 []).
Definition chz_1RB0LC_1LA1RA_0RA0LD____0LC : list lstep := [SWin 2; SWinR 2].

Lemma run_z_1RB0LC_1LA1RA_0RA0LD____0LC : srun tm false true chz_1RB0LC_1LA1RA_0RA0LD____0LC Z0_1RB0LC_1LA1RA_0RA0LD____0LC = Some (Z1_1RB0LC_1LA1RA_0RA0LD____0LC, 0, 4).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
