(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0LC_1LA1RA_0RA0RD_0LD0LC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z0_1RB0LC_1LA1RA_0RA0RD_0LD0LC /\
