  - destruct (gz_1RB0LC_1LA1RA_0RD1LC_1RA0LC p q0 E) as (HA & HB).
    exists (0 * 0 + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0LC_1LA1RA_0RD1LC_1RA0LC Z0_1RB0LC_1LA1RA_0RD1LC_1RA0LC Z1_1RB0LC_1LA1RA_0RD1LC_1RA0LC 0 6
               run_z_1RB0LC_1LA1RA_0RD1LC_1RA0LC (Jp q0 ++ [S0;S1;S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0LC_1LA1RA_0RD1LC_1RA0LC p j' q0 E) as (HA & HB).
    exists (4 * j' + 10). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0LC_1LA1RA_0RD1LC_1RA0LC P0_1RB0LC_1LA1RA_0RD1LC_1RA0LC P1_1RB0LC_1LA1RA_0RD1LC_1RA0LC 4 10
               run_p_1RB0LC_1LA1RA_0RD1LC_1RA0LC (Jp q0 ++ [S0;S1;S0]) [] j'
