    apply (lap_of_run tm Cc true true cho_1RB0LC_1LA1RA_0RD1LC_1RA0LC B0_1RB0LC_1LA1RA_0RD1LC_1RA0LC B1_1RB0LC_1LA1RA_0RD1LC_1RA0LC 4 12 p j' [] []).
    + exact run_ovf_1RB0LC_1LA1RA_0RD1LC_1RA0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LC_1LA1RA_0RD1LC_1RA0LC p j' E).
    + exact (geo_1RB0LC_1LA1RA_0RD1LC_1RA0LC p j' E).
    + lia.
