(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0LC_1LA1RA_1LD1LC_0RD0RA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0;S1;S0]) [] 0 Z0_1RB0LC_1LA1RA_1LD1LC_0RD0RA /\
  cden (Jp q0 ++ [S0;S1;S0]) [] 0 Z1_1RB0LC_1LA1RA_1LD1LC_0RD0RA = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (JpCounter.cview_some_J p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB0LC_1LA1RA_1LD1LC_0RD0RA, cden, Z0_1RB0LC_1LA1RA_1LD1LC_0RD0RA, Z1_1RB0LC_1LA1RA_1LD1LC_0RD0RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB0LC_1LA1RA_1LD1LC_0RD0RA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0;S1;S0]) [] j P0_1RB0LC_1LA1RA_1LD1LC_0RD0RA /\
  cden (Jp q0 ++ [S0;S1;S0]) [] j P1_1RB0LC_1LA1RA_1LD1LC_0RD0RA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB0LC_1LA1RA_1LD1LC_0RD0RA, cden, P0_1RB0LC_1LA1RA_1LD1LC_0RD0RA, P1_1RB0LC_1LA1RA_1LD1LC_0RD0RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
