  - destruct (gz_1RB0LC_1LA1RA_1LD1LC_0RD0RA p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0LC_1LA1RA_1LD1LC_0RD0RA Z0_1RB0LC_1LA1RA_1LD1LC_0RD0RA Z1_1RB0LC_1LA1RA_1LD1LC_0RD0RA 0 4
               run_z_1RB0LC_1LA1RA_1LD1LC_0RD0RA (Jp q0 ++ [S0;S1;S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0LC_1LA1RA_1LD1LC_0RD0RA p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0LC_1LA1RA_1LD1LC_0RD0RA P0_1RB0LC_1LA1RA_1LD1LC_0RD0RA P1_1RB0LC_1LA1RA_1LD1LC_0RD0RA 4 8
