Lemma geo_1RB0LC_1LA1RA_1LD1LC_0RD0RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_1LA1RA_1LD1LC_0RD0RA) = lift (Cc (Pos.succ p)).
