(** ** The lap *)

Lemma lap_1RB0LC_1LA1RA_1LD1LC_0RD0RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
