    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0LC_1LA1RA_1LD1LC_0RD0RA
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0LC_1LA1RA_1LD1LC_0RD0RA
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SWinL 2]).
    vm_compute; reflexivity.
  - (* B0 *)
