Lemma gz_1RB0LC_1LA1RD_0RA0LC_1RB___ : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z0_1RB0LC_1LA1RD_0RA0LC_1RB___ /\
