Lemma gsi_1RB0LC_1LA1RD_0RA1LC_1RA0LB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_111_101_1 q0 ++ [S0;S1;S0]) [] j A0_1RB0LC_1LA1RD_0RA1LC_1RA0LB.
