Lemma gsi_1RB0LC_1LA1RD_0RD0LC_1RA___ : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_000_010_01 q0 ++ [S0]) [] j A0_1RB0LC_1LA1RD_0RD0LC_1RA___.
