(** ** The lap *)

Lemma lap_1RB0LC_1LA1RD_0RD0LC_1RA___ : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
