    apply (lap_of_run tm Cc true true cho_1RB0LC_1LA1RD_0RD0LC_1RA___ B0_1RB0LC_1LA1RD_0RD0LC_1RA___ B1_1RB0LC_1LA1RD_0RD0LC_1RA___ 6 12 p j' [] []).
    + exact run_ovf_1RB0LC_1LA1RD_0RD0LC_1RA___.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LC_1LA1RD_0RD0LC_1RA___ p j' E).
    + exact (geo_1RB0LC_1LA1RD_0RD0LC_1RA___ p j' E).
    + lia.
