Lemma lapi_1RB0LC_1LA1RD_0RD1LC_1LB1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
