(** 1RB0LC_1LA1RD_1LA0LA_0RD0LA *)
Definition tm_1RB0LC_1LA1RD_1LA0LA_0RD0LA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S0 DL StA
  | StD, S0 => mk S0 DR StD | StD, S1 => mk S0 DL StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
