Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LC_1LA1RD_1LA0LA_0RD0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Dp q0 ++ [S0]) [] j A0_1RB0LC_1LA1RD_1LA0LA_0RD0LA.
Proof.
  intros p j q0 E. destruct (DpCounter.cview_some_D p j q0 E) as (H1 & _).
  unfold Cc_1RB0LC_1LA1RD_1LA0LA_0RD0LA, cden, A0_1RB0LC_1LA1RD_1LA0LA_0RD0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB0LC_1LA1RD_1LA0LA_0RD0LA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Dp q0 ++ [S0]) [] j A1_1RB0LC_1LA1RD_1LA0LA_0RD0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (DpCounter.cview_some_D p j q0 E) as (_ & H2).
  unfold Cc_1RB0LC_1LA1RD_1LA0LA_0RD0LA, cden, A1_1RB0LC_1LA1RD_1LA0LA_0RD0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0LC_1LA1RD_1LA0LA_0RD0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 8), (cden (Dp q0 ++ [S0]) [] j A1_1RB0LC_1LA1RD_1LA0LA_0RD0LA).
  split; [lia|]. split; [| exact (gei_1RB0LC_1LA1RD_1LA0LA_0RD0LA p j q0 E)].
  rewrite (gsi_1RB0LC_1LA1RD_1LA0LA_0RD0LA p j q0 E).
  exact (srun_sound tm false true chi_1RB0LC_1LA1RD_1LA0LA_0RD0LA A0_1RB0LC_1LA1RD_1LA0LA_0RD0LA A1_1RB0LC_1LA1RD_1LA0LA_0RD0LA 4 8
           run_int_1RB0LC_1LA1RD_1LA0LA_0RD0LA (Dp q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB0LC_1LA1RD_1LA0LA_0RD0LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LC_1LA1RD_1LA0LA_0RD0LA.
Proof.
  intros p j E. destruct (DpCounter.cview_none_D p j E) as (H1 & _).
  unfold Cc_1RB0LC_1LA1RD_1LA0LA_0RD0LA, cden, B0_1RB0LC_1LA1RD_1LA0LA_0RD0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0LC_1LA1RD_1LA0LA_0RD0LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LC_1LA1RD_1LA0LA_0RD0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_1LA1RD_1LA0LA_0RD0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (DpCounter.cview_none_D p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LC_1LA1RD_1LA0LA_0RD0LA
             = (StA, (rep [S0;S0] (S j) ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_1RB0LC_1LA1RD_1LA0LA_0RD0LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S0;S0] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB0LC_1LA1RD_1LA0LA_0RD0LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_1RB0LC_1LA1RD_1LA0LA_0RD0LA. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB0LC_1LA1RD_1LA0LA_0RD0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LC_1LA1RD_1LA0LA_0RD0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LC_1LA1RD_1LA0LA_0RD0LA B0_1RB0LC_1LA1RD_1LA0LA_0RD0LA B1_1RB0LC_1LA1RD_1LA0LA_0RD0LA 4 12 p j' [] []).
    + exact run_ovf_1RB0LC_1LA1RD_1LA0LA_0RD0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LC_1LA1RD_1LA0LA_0RD0LA p j' E).
    + exact (geo_1RB0LC_1LA1RD_1LA0LA_0RD0LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LC_1LA1RD_1LA0LA_0RD0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 8.
  assert (H : match csteps tm 8 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 8 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LC_1LA1RD_1LA0LA_0RD0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_1LA1RD_1LA0LA_0RD0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LC_1LA1RD_1LA0LA_0RD0LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_1LA1RD_1LA0LA_0RD0LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LC_1LA1RD_1LA0LA_0RD0LA : forall t, ~ In t pins_1RB0LC_1LA1RD_1LA0LA_0RD0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0LC_1LA1RD_1LA0LA_0RD0LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LA1RD_1LA0LA_0RD0LA [] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LA1RD_1LA0LA_0RD0LA [SWinR 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LA1RD_1LA0LA_0RD0LA [SWinR 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LA1RD_1LA0LA_0RD0LA [SWinR 4; SCycL 2 0; SWin 1; SWinL 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LA1RD_1LA0LA_0RD0LA [SWinR 4; SCycL 2 0; SWin 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LA1RD_1LA0LA_0RD0LA [SWinR 3] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LA1RD_1LA0LA_0RD0LA [SWinR 4; SCycL 2 0; SWin 1; SWinL 3] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LA1RD_1LA0LA_0RD0LA [SWinR 4; SCycL 2 0; SWin 1; SWinL 3; SCycR 2; SWin 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB0LC_1LA1RD_1LA0LA_0RD0LA : NeverQuasiHaltsTr tm_1RB0LC_1LA1RD_1LA0LA_0RD0LA.
Proof.
  apply (glue_neverqhtr tm_1RB0LC_1LA1RD_1LA0LA_0RD0LA pins_1RB0LC_1LA1RD_1LA0LA_0RD0LA Cc 1).
  - exact boot_1RB0LC_1LA1RD_1LA0LA_0RD0LA.
  - intros p _. apply lap_1RB0LC_1LA1RD_1LA0LA_0RD0LA.
  - intros t Ht p _. apply fire_1RB0LC_1LA1RD_1LA0LA_0RD0LA. exact Ht.
Qed.

Theorem nonhalt_1RB0LC_1LA1RD_1LA0LA_0RD0LA : NonHalt tm_1RB0LC_1LA1RD_1LA0LA_0RD0LA.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB0LC_1LA1RD_1LA0LA_0RD0LA. Qed.

