(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0LC_1LA1RD_1LA0LC_0RD0LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Dp q0 ++ [S0]) [] 0 Z0_1RB0LC_1LA1RD_1LA0LC_0RD0LA /\
