(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LC_1LB1RA_0LA1LD_0RB1LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB0LC_1LB1RA_0LA1LD_0RB1LC.
