  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LC_1LB1RA_0RA1LD_0RB1LC p (pow2 j)).
  - exists (4 * j + 11), (cden [] [] j BB1_1RB0LC_1LB1RA_0RA1LD_0RB1LC).
    split; [lia|]. split; [| exact (gbo_1RB0LC_1LB1RA_0RA1LD_0RB1LC j)].
    rewrite (gso_1RB0LC_1LB1RA_0RA1LD_0RB1LC p j E).
