Lemma fireo_1RB0LC_1LB1RA_0RA1LD_1LA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_1LB1RA_0RA1LD_1LA1LC = Some t ->
  forall p j, cview p = (S j, None) ->
